using System;using System.IO;using System.Text;using System.Diagnostics;using System.Collections.Generic;using System.Web.Script.Serialization;
public class SteamInstallRepairResult {public string Backup,Launcher,Error;public int Moved;}
public static class SteamInstallRepair {
 public const string LauncherName="Start-Steam-Legacy.cmd";
 public const string LauncherText="@echo off\r\ncd /d \"%~dp0\"\r\nstart \"\" \"%~dp0steam.exe\" -no-cef-sandbox\r\n";
 static bool WriteLauncher(string path){if(File.Exists(path)){if(File.ReadAllText(path)!=LauncherText)throw new Exception("Existing recovery launcher changed; it was retained.");return false;}string temp=path+".tmp-"+Guid.NewGuid().ToString("N");try{File.WriteAllText(temp,LauncherText,Encoding.ASCII);File.Move(temp,path);return true;}finally{if(File.Exists(temp))File.Delete(temp);}}
 static readonly string[] Names={"tier0_s.dll","tier0_s64.dll"};
 public static void Validate(string root,bool is64){if(!Core.IsSteamRoot(root))throw new Exception("Select the Steam installation folder containing steam.exe.");string full=Path.GetFullPath(root);for(string p=full;!string.IsNullOrEmpty(p);p=Path.GetDirectoryName(p))if((File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new Exception("Steam folder is a reparse point.");using(var reader=new BinaryReader(File.OpenRead(Core.Inside(root,"steam.exe")))){if(reader.BaseStream.Length<64||reader.ReadUInt16()!=0x5a4d)throw new Exception("steam.exe is not a Windows executable.");reader.BaseStream.Position=0x3c;int offset=reader.ReadInt32();if(offset<64||offset>reader.BaseStream.Length-6)throw new Exception("Invalid steam.exe header.");reader.BaseStream.Position=offset;if(reader.ReadUInt32()!=0x4550)throw new Exception("Invalid steam.exe header.");ushort machine=reader.ReadUInt16();if(machine==0x8664&&!is64)throw new Exception("64-bit Steam cannot run on 32-bit Windows. Reinstall a 32-bit Steam bootstrapper and disable architecture-spoofing compatibility settings before retrying.");if(machine!=0x14c&&machine!=0x8664)throw new Exception("Unsupported Steam executable architecture.");}foreach(string name in Names)Core.Inside(root,name);string launcher=Core.Inside(root,LauncherName);if(File.Exists(launcher)&&File.ReadAllText(launcher)!=LauncherText)throw new Exception("An unrelated "+LauncherName+" already exists; rename it before retrying.");}
 static List<GameProcess> Clients(string root){var snapshot=GameTools.Snapshot();foreach(string name in new[]{"steam","steamwebhelper"})foreach(var process in Process.GetProcessesByName(name))using(process){if(!snapshot.Exists(p=>p.Id==process.Id)){try{if(process.HasExited)continue;}catch{}throw new Exception("Cannot inspect a Steam process. Exit Steam completely before retrying.");}}return snapshot.FindAll(p=>GameTools.Within(root,p.Path)).FindAll(p=>{string name=Path.GetFileName(p.Path);return name.Equals("steam.exe",StringComparison.OrdinalIgnoreCase)||name.Equals("steamwebhelper.exe",StringComparison.OrdinalIgnoreCase);});}
 public static void EnsureStopped(string root){if(Clients(root).Count>0)throw new Exception("Steam is still running. Exit Steam completely and retry; no forced termination was performed.");}
 static void StopSteam(string root,Action<string> log){if(Clients(root).Count==0)return;log("Requesting normal Steam shutdown before first-install repair.");using(var p=Process.Start(new ProcessStartInfo(Core.Inside(root,"steam.exe"),"-shutdown"){UseShellExecute=false,WorkingDirectory=root})){if(p==null)throw new Exception("Could not request Steam shutdown.");}var timer=Stopwatch.StartNew();while(timer.Elapsed<TimeSpan.FromSeconds(30)){if(Clients(root).Count==0)return;System.Threading.Thread.Sleep(250);}EnsureStopped(root);}
 // Only these two root DLLs are moved. No game, account, client configuration or compatibility setting is changed.
 public static SteamInstallRepairResult Prepare(string root,bool is64,Action idle,Action<string> log){Validate(root,is64);idle();var result=new SteamInstallRepairResult{Launcher=Core.Inside(root,LauncherName)};var files=new List<string>();foreach(string name in Names)if(File.Exists(Core.Inside(root,name)))files.Add(name);if(files.Count==0){WriteLauncher(result.Launcher);log("Bootstrap DLLs already absent; retrying the same recovery launch.");return result;}
 string backup=Core.Inside(root,"LegacySteamFixer-InstallRepair/"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(backup);result.Backup=backup;var hashes=new Dictionary<string,string>();foreach(string name in files)hashes[name]=Core.Hash(Core.Inside(root,name));File.WriteAllText(Path.Combine(backup,"backup.json"),new JavaScriptSerializer().Serialize(new{Root=Path.GetFullPath(root),Files=hashes}),Encoding.UTF8);var moved=new List<string>();bool madeLauncher=false;try{idle();foreach(string name in files){string source=Core.Inside(root,name);if(Core.Hash(source)!=hashes[name])throw new Exception("Steam files changed during preparation; retry after closing Steam.");File.Move(source,Core.Inside(backup,name));moved.Add(name);log("Backed up root DLL: "+name);}madeLauncher=WriteLauncher(result.Launcher);result.Moved=moved.Count;return result;}catch(Exception failure){var errors=new List<string>();foreach(string name in moved)try{File.Move(Core.Inside(backup,name),Core.Inside(root,name));}catch(Exception e){errors.Add(e.Message);}if(madeLauncher)try{File.Delete(result.Launcher);}catch(Exception e){errors.Add(e.Message);}throw new Exception(failure.Message+(errors.Count==0?"\nMoved DLLs restored.":"\nRollback incomplete. Keep backup: "+backup+"\n"+string.Join("\n",errors.ToArray())));}}
 public static SteamInstallRepairResult Repair(string root,Action<string> log){Validate(root,Environment.Is64BitOperatingSystem);StopSteam(root,log);if(ZstdSupport.IsAdministrator())return Prepare(root,Environment.Is64BitOperatingSystem,()=>EnsureStopped(root),log);string path=Path.Combine(Path.GetTempPath(),"Fixer-InstallRepair-"+Guid.NewGuid().ToString("N")+".json");try{using(var p=Process.Start(new ProcessStartInfo(Core.Inside(Core.Base,"LegacySteamFixer.exe"),"--repair-steam-install "+ZstdSupport.Quote(root)+" "+ZstdSupport.Quote(path)){UseShellExecute=true,Verb="runas",WorkingDirectory=Core.Base})){if(p==null)throw new Exception("Could not elevate Fixer.");p.WaitForExit();if(!File.Exists(path))throw new Exception("Repair helper returned no result (exit "+p.ExitCode+").");var result=new JavaScriptSerializer().Deserialize<SteamInstallRepairResult>(File.ReadAllText(path));if(result==null||!string.IsNullOrEmpty(result.Error))throw new Exception(result==null?"Invalid repair result.":result.Error);return result;}}finally{if(File.Exists(path))File.Delete(path);}}
 public static int Elevated(string root,string output){SteamInstallRepairResult result;try{if(!ZstdSupport.IsAdministrator())throw new Exception("Administrator privileges required.");result=Prepare(root,Environment.Is64BitOperatingSystem,()=>EnsureStopped(root),s=>{});}catch(Exception e){result=new SteamInstallRepairResult{Error=e.Message};}File.WriteAllText(output,new JavaScriptSerializer().Serialize(result),Encoding.UTF8);return string.IsNullOrEmpty(result.Error)?0:1;}
 public static void Launch(string root){Process.Start(new ProcessStartInfo(Core.Inside(root,"steam.exe"),"-no-cef-sandbox"){UseShellExecute=false,WorkingDirectory=root});}
}
